-- TripRaft States / Subdivisions enrichment
-- Snapshot: 2026-10-09; original records: 1,739; countries: 190.
-- Existing id, country_id, state_name and created_at are preserved.
-- Existing retired_at is preserved. Subdivision types populated for all rows.
-- ISO 3166-2 codes are populated only where a defensible subdivision match exists.
-- ISO reference: pycountry 24.6.1 / Debian iso-codes; supplementary 2025 PCGN
-- topographic factfiles for Burkina Faso and Norway.
-- IMPORTANT: Existing database has nonstandard groupings and some newer divisions.
-- NULL iso3166_2 is intentional (not missing import data).
-- SQL designed for SQLite 3.24+ and matching pre-populated countries table.
PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS states (
    id INTEGER PRIMARY KEY,
    country_id INTEGER NOT NULL REFERENCES countries(id) ON DELETE CASCADE,
    state_name TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d','now')),
    iso3166_2 TEXT UNIQUE, division_type TEXT, updated_at TEXT, retired_at TEXT,
    UNIQUE (country_id, state_name), UNIQUE(id, country_id)
);
-- Abort transaction rather than silently overwrite any pre-existing different identity.
CREATE TEMP TABLE IF NOT EXISTS _tripraft_state_identity_guard (ok INTEGER NOT NULL CHECK(ok=1));
